-- supabase/seed.sql
-- Full demo workspace seed: includes populated floors, components, roster,
-- neighborhoods, and annotations by inserting a demo office payload.

begin;

-- Fixed demo auth user; profile row is created by handle_new_user trigger.
insert into auth.users (id, email, encrypted_password, email_confirmed_at)
values (
  'aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa',
  'demo-owner@floorcraft.local',
  'seed-password-not-used',
  now()
)
on conflict (id) do update
set email = excluded.email,
    encrypted_password = excluded.encrypted_password,
    email_confirmed_at = excluded.email_confirmed_at;

-- Team for the seeded workspace.
